#!/usr/bin/env python3
import base64,gzip,pathlib
ROOT=pathlib.Path(__file__).resolve().parents[1]
FILES={
  "app.js": "[... truncated for brevity in this interface ...]KAAA=",
  "styles.css": "",
}
for name,payload in FILES.items():
    (ROOT/name).write_bytes(gzip.decompress(base64.b64decode(payload)))
    print("materialized",name)
